package com.metalurgica.sistemagestaoindustrial.service;

import com.metalurgica.sistemagestaoindustrial.domain.*; import com.metalurgica.sistemagestaoindustrial.dto.response.*; import com.metalurgica.sistemagestaoindustrial.exception.*; import com.metalurgica.sistemagestaoindustrial.importacao.*; import com.metalurgica.sistemagestaoindustrial.mapper.ImportacaoProducaoMapper; import com.metalurgica.sistemagestaoindustrial.repository.*; import org.springframework.beans.factory.annotation.Value; import org.springframework.data.domain.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.multipart.MultipartFile; import java.nio.charset.StandardCharsets; import java.security.*; import java.time.OffsetDateTime; import java.util.*;

@Service public class ImportacaoProducaoService {
 private final ImportacaoProducaoRepository repository; private final ResultadoLinhaImportacaoRepository resultadoRepository; private final EmpresaService empresaService; private final SetorRepository setorRepository; private final ExcelImportReader reader; private final ImportacaoValidator validator; private final RegistroProducaoRepository producaoRepository; private final ImportacaoProducaoMapper mapper; private final int maxLinhas;
 public ImportacaoProducaoService(ImportacaoProducaoRepository r,ResultadoLinhaImportacaoRepository rr,EmpresaService e,SetorRepository s,ExcelImportReader x,ImportacaoValidator v,RegistroProducaoRepository p,ImportacaoProducaoMapper m,@Value("${app.importacao.max-linhas:10000}") int max){repository=r;resultadoRepository=rr;empresaService=e;setorRepository=s;reader=x;validator=v;producaoRepository=p;mapper=m;maxLinhas=max;}
 @Transactional public ImportacaoProducaoResponse validate(Long empresaId,Long setorId,MultipartFile file){return process(empresaId,setorId,file,false);}
 @Transactional public ImportacaoProducaoResponse importFile(Long empresaId,Long setorId,MultipartFile file){return process(empresaId,setorId,file,true);}
 @Transactional(readOnly=true) public Page<ImportacaoProducaoResponse> list(Long e,Long setorId,StatusImportacao status,Pageable p){empresaService.find(e);Page<ImportacaoProducao> page=status!=null?repository.findByEmpresaIdAndStatus(e,status,p):setorId!=null?repository.findByEmpresaIdAndSetorId(e,setorId,p):repository.findByEmpresaId(e,p);return page.map(mapper::toResponse);}
 @Transactional(readOnly=true) public ImportacaoProducaoResponse get(Long e,Long id){return mapper.toResponse(find(e,id));}
 @Transactional(readOnly=true) public Page<ResultadoLinhaImportacaoResponse> lines(Long e,Long id,Pageable p){find(e,id);return resultadoRepository.findByImportacaoId(id,p).map(mapper::toResponse);}
 private ImportacaoProducaoResponse process(Long empresaId,Long setorId,MultipartFile file,boolean persist){var empresa=empresaService.find(empresaId);var setor=setorRepository.findByIdAndEmpresaId(setorId,empresaId).orElseThrow(()->new ResourceNotFoundException("Setor não encontrado nesta empresa."));String hash=hash(file);if(repository.existsByEmpresaIdAndSetorIdAndHashArquivoAndStatus(empresaId,setorId,hash,StatusImportacao.CONCLUIDA))throw new DuplicateResourceException("ARQUIVO_DUPLICADO");var imp=new ImportacaoProducao();imp.setEmpresa(empresa);imp.setSetor(setor);imp.setNomeArquivo(file==null?"arquivo":Objects.requireNonNullElse(file.getOriginalFilename(),"arquivo.xlsx"));imp.setHashArquivo(hash);imp.touchCreate();imp.setStatus(StatusImportacao.VALIDANDO);repository.save(imp);ExcelReadResult read;try{read=reader.read(file);if(read.totalLinhas()>maxLinhas)throw new IllegalArgumentException("LIMITE_LINHAS_EXCEDIDO");}catch(RuntimeException ex){imp.setStatus(StatusImportacao.REJEITADA);imp.setFinalizadoEm(OffsetDateTime.now());imp.setLinhasInvalidas(1);imp.setTotalLinhas(0);repository.save(imp);throw ex;}var validation=validator.validate(empresaId,setorId,read);imp.setTotalLinhas(validation.totalLinhas());imp.setLinhasValidas(validation.validas().size());imp.setLinhasInvalidas(validation.erros().size());saveErrors(imp,validation.erros());if(!validation.isValida()){imp.setStatus(StatusImportacao.REJEITADA);imp.setFinalizadoEm(OffsetDateTime.now());repository.save(imp);return mapper.toResponse(imp);}if(!persist){imp.setStatus(StatusImportacao.VALIDADA);imp.setFinalizadoEm(OffsetDateTime.now());repository.save(imp);return mapper.toResponse(imp);}imp.setStatus(StatusImportacao.IMPORTANDO);repository.save(imp);for(var line:validation.validas()){var r=new RegistroProducao();r.setEmpresa(empresa);r.setSetor(setor);r.setFuncionario(line.funcionario());r.setPeca(line.peca());r.setMaquina(line.maquina());r.setTurno(line.turno());r.setQuantidade(line.quantidade());r.setInicio(line.inicio());r.setFim(line.fim());r.setOrigem(OrigemProducao.IMPORTACAO);r.setImportacao(imp);r.setImportacaoLinha(line.linha().linha());r.touchForCreate();producaoRepository.save(r);}imp.setLinhasImportadas(validation.validas().size());imp.setStatus(StatusImportacao.CONCLUIDA);imp.setFinalizadoEm(OffsetDateTime.now());return mapper.toResponse(repository.save(imp));}
 private void saveErrors(ImportacaoProducao imp,List<ImportacaoLinhaErro> errors){var entities=errors.stream().map(e->{var r=new ResultadoLinhaImportacao();r.setImportacao(imp);r.setNumeroLinha(e.linha());r.setStatus("ERRO");r.setCodigoFuncionario(e.codigoFuncionario());r.setCodigoPeca(e.codigoPeca());r.setCodigoErro(e.codigo());r.setMensagem(e.mensagem());return r;}).toList();resultadoRepository.saveAll(entities);}
 private ImportacaoProducao find(Long e,Long id){empresaService.find(e);return repository.findByIdAndEmpresaId(id,e).orElseThrow(()->new ResourceNotFoundException("Importação não encontrada nesta empresa."));}
 private static String hash(MultipartFile f){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(f==null?new byte[0]:f.getBytes()),StandardCharsets.UTF_8);}catch(Exception e){throw new IllegalStateException("Não foi possível calcular hash do arquivo.");}}
}
